#include <algorithm>
#include <cmath>
#include <cstdint>
#include <deque>
#include <map>
#include <optional>
#include <tuple>
#include <utility>
#include <vector>

struct Input { std::uint32_t sequence; int moveX; int moveY; };
struct PlayerSnapshot { int id; int x; int y; std::uint32_t lastInput; };
struct Snapshot { std::int64_t tick; std::vector<PlayerSnapshot> players; };

namespace
{
    std::pair<int, int> moved(int x, int y, const Input& in, int speed)
    {
        const int mx{ std::clamp(in.moveX, -1, 1) };
        const int my{ std::clamp(in.moveY, -1, 1) };
        return { std::clamp(x + mx * speed, 0, 1000), std::clamp(y + my * speed, 0, 1000) };
    }
}

class GameServer
{
public:
    explicit GameServer(int speed) : speed_{ speed } {}

    int addPlayer(int x, int y)
    {
        const int id{ static_cast<int>(players_.size()) + 1 };
        players_[id] = Player{ std::clamp(x, 0, 1000), std::clamp(y, 0, 1000), 0, {} };
        return id;
    }

    void receiveInput(int player, const Input& in)
    {
        const auto it{ players_.find(player) };
        if (it == players_.end()) return;
        Player& p{ it->second };
        if (in.sequence <= p.lastInput || p.queued.size() >= 64) return;
        p.queued.emplace(in.sequence, in);
    }

    void teleport(int player, int x, int y)
    {
        const auto it{ players_.find(player) };
        if (it == players_.end()) return;
        it->second.x = std::clamp(x, 0, 1000);
        it->second.y = std::clamp(y, 0, 1000);
    }

    void tick()
    {
        ++tick_;
        std::map<int, std::pair<int, int>> frame;
        for (auto& [id, p] : players_)
        {
            for (const auto& [sequence, in] : p.queued)
            {
                std::tie(p.x, p.y) = moved(p.x, p.y, in, speed_);
                p.lastInput = sequence;
            }
            p.queued.clear();
            frame[id] = { p.x, p.y };
        }
        history_.emplace_back(tick_, std::move(frame));
        if (history_.size() > 64) history_.pop_front();
    }

    Snapshot snapshot() const
    {
        Snapshot s{ tick_, {} };
        for (const auto& [id, p] : players_) s.players.push_back({ id, p.x, p.y, p.lastInput });
        return s;
    }

    int hitscan(int shooter, double viewTick, double dirX, double dirY, double range, double radius) const
    {
        const auto me{ players_.find(shooter) };
        if (me == players_.end()) return 0;
        const double length{ std::hypot(dirX, dirY) };
        if (length == 0) return 0;
        const double ux{ dirX / length };
        const double uy{ dirY / length };
        const double ox{ static_cast<double>(me->second.x) };
        const double oy{ static_cast<double>(me->second.y) };
        const double t{ std::clamp(viewTick, static_cast<double>(tick_ - 32), static_cast<double>(tick_)) };

        int best{ 0 };
        double bestAlong{ 0 };
        for (const auto& [id, p] : players_)
        {
            if (id == shooter) continue;
            const auto at{ rewound(id, t) };
            if (!at) continue;
            const double along{ std::clamp((at->first - ox) * ux + (at->second - oy) * uy, 0.0, range) };
            const double px{ ox + ux * along - at->first };
            const double py{ oy + uy * along - at->second };
            if (px * px + py * py > radius * radius) continue;
            if (best == 0 || along < bestAlong)
            {
                best = id;
                bestAlong = along;
            }
        }
        return best;
    }

private:
    struct Player
    {
        int x;
        int y;
        std::uint32_t lastInput;
        std::map<std::uint32_t, Input> queued;
    };

    std::optional<std::pair<double, double>> recorded(int id, std::int64_t tick) const
    {
        for (const auto& [t, frame] : history_)
        {
            if (t != tick) continue;
            const auto it{ frame.find(id) };
            if (it == frame.end()) return std::nullopt;
            return std::pair{ static_cast<double>(it->second.first), static_cast<double>(it->second.second) };
        }
        return std::nullopt;
    }

    std::optional<std::pair<double, double>> rewound(int id, double t) const
    {
        const auto lo{ static_cast<std::int64_t>(std::floor(t)) };
        const auto hi{ static_cast<std::int64_t>(std::ceil(t)) };
        const auto a{ recorded(id, lo) };
        const auto b{ recorded(id, hi) };
        if (!a || !b) return std::nullopt;
        const double f{ t - static_cast<double>(lo) };
        return std::pair{ a->first + (b->first - a->first) * f, a->second + (b->second - a->second) * f };
    }

    int speed_;
    std::int64_t tick_{ 0 };
    std::map<int, Player> players_;
    std::deque<std::pair<std::int64_t, std::map<int, std::pair<int, int>>>> history_;
};

class GameClient
{
public:
    GameClient(int playerId, int speed, int x, int y)
        : id_{ playerId }, speed_{ speed }, x_{ std::clamp(x, 0, 1000) }, y_{ std::clamp(y, 0, 1000) }
    {
    }

    Input makeInput(int moveX, int moveY)
    {
        const Input in{ ++sequence_, std::clamp(moveX, -1, 1), std::clamp(moveY, -1, 1) };
        std::tie(x_, y_) = moved(x_, y_, in, speed_);
        pending_.push_back(in);
        return in;
    }

    void receiveSnapshot(const Snapshot& s)
    {
        if (newest_ && s.tick <= *newest_) return;
        newest_ = s.tick;
        for (const PlayerSnapshot& p : s.players)
        {
            if (p.id == id_)
            {
                while (!pending_.empty() && pending_.front().sequence <= p.lastInput) pending_.pop_front();
                x_ = p.x;
                y_ = p.y;
                for (const Input& in : pending_) std::tie(x_, y_) = moved(x_, y_, in, speed_);
                continue;
            }
            auto& samples{ remote_[p.id] };
            samples.push_back({ s.tick, p.x, p.y });
            if (samples.size() > 32) samples.pop_front();
        }
    }

    std::pair<int, int> position() const { return { x_, y_ }; }
    std::size_t pendingInputs() const { return pending_.size(); }

    std::optional<std::pair<double, double>> remotePosition(int playerId, double tick) const
    {
        const auto it{ remote_.find(playerId) };
        if (it == remote_.end() || it->second.empty()) return std::nullopt;
        const auto& s{ it->second };
        if (tick <= static_cast<double>(s.front().tick)) return std::pair{ double(s.front().x), double(s.front().y) };
        if (tick >= static_cast<double>(s.back().tick)) return std::pair{ double(s.back().x), double(s.back().y) };
        for (std::size_t i{ 1 }; i < s.size(); ++i)
        {
            if (tick > static_cast<double>(s[i].tick)) continue;
            const Sample& a{ s[i - 1] };
            const Sample& b{ s[i] };
            const double f{ (tick - static_cast<double>(a.tick)) / static_cast<double>(b.tick - a.tick) };
            return std::pair{ a.x + (b.x - a.x) * f, a.y + (b.y - a.y) * f };
        }
        return std::pair{ double(s.back().x), double(s.back().y) };
    }

private:
    struct Sample { std::int64_t tick; int x; int y; };

    int id_;
    int speed_;
    int x_;
    int y_;
    std::uint32_t sequence_{ 0 };
    std::deque<Input> pending_;
    std::optional<std::int64_t> newest_;
    std::map<int, std::deque<Sample>> remote_;
};

unitTests:
#include <cmath>
#include <deque>
bool isAt(const std::optional<std::pair<double, double>>& p, double x, double y) {
    return p.has_value() && std::abs(p->first - x) < 1e-9 && std::abs(p->second - y) < 1e-9;
}
TEST("the server applies and checks inputs") {
    GameServer server{ 10 };
    CHECK_EQ(server.addPlayer(5, 995), 1);
    CHECK_EQ(server.addPlayer(2000, -3), 2);
    server.receiveInput(1, { 1, -1, 1 });
    server.tick();
    Snapshot s{ server.snapshot() };
    CHECK_EQ(s.tick, 1);
    CHECK(s.players.size() == 2);
    if (s.players.size() == 2) {
        CHECK(s.players[0].x == 0 && s.players[0].y == 1000 && s.players[0].lastInput == 1);
        CHECK(s.players[1].x == 1000 && s.players[1].y == 0 && s.players[1].lastInput == 0);
    }
    server.receiveInput(1, { 1, 1, 0 });
    server.receiveInput(1, { 3, 5, 0 });
    server.receiveInput(1, { 2, 0, -7 });
    server.receiveInput(99, { 1, 1, 1 });
    server.tick();
    s = server.snapshot();
    CHECK(s.players.size() == 2 && s.players[0].x == 10 && s.players[0].y == 990 && s.players[0].lastInput == 3);
    server.receiveInput(1, { 4, 1, 0 });
    server.receiveInput(1, { 4, 1, 0 });
    server.tick();
    s = server.snapshot();
    CHECK(s.players.size() == 2 && s.players[0].x == 20);
    server.teleport(2, 50, 1200);
    server.teleport(99, 1, 1);
    s = server.snapshot();
    CHECK(s.players.size() == 2 && s.players[1].x == 50 && s.players[1].y == 1000);
    CHECK_EQ(s.tick, 3);
}
TEST("prediction hides the latency") {
    GameServer server{ 5 };
    const int me{ server.addPlayer(500, 500) };
    GameClient client{ me, 5, 500, 500 };
    std::deque<std::pair<int, Input>> up;
    std::deque<std::pair<int, Snapshot>> down;
    bool smooth{ true };
    for (int t{ 0 }; t < 40; ++t) {
        up.emplace_back(t + 3, client.makeInput(1, 0));
        while (!up.empty() && up.front().first <= t) { server.receiveInput(me, up.front().second); up.pop_front(); }
        server.tick();
        down.emplace_back(t + 3, server.snapshot());
        while (!down.empty() && down.front().first <= t) { client.receiveSnapshot(down.front().second); down.pop_front(); }
        if (client.position() != std::pair{ 500 + 5 * (t + 1), 500 }) smooth = false;
    }
    CHECK(smooth);
    CHECK_EQ(client.pendingInputs(), 6u);
    const Snapshot last{ server.snapshot() };
    CHECK(!last.players.empty() && last.players[0].x == 500 + 5 * 37);
}
TEST("the server corrects a wrong prediction") {
    GameServer server{ 5 };
    const int me{ server.addPlayer(500, 500) };
    GameClient client{ me, 5, 500, 500 };
    std::deque<std::pair<int, Input>> up;
    std::deque<std::pair<int, Snapshot>> down;
    int yAt22{ 0 }, yAt23{ 0 };
    for (int t{ 0 }; t < 30; ++t) {
        up.emplace_back(t + 3, client.makeInput(1, 0));
        while (!up.empty() && up.front().first <= t) { server.receiveInput(me, up.front().second); up.pop_front(); }
        if (t == 20) server.teleport(me, 100, 100);
        server.tick();
        down.emplace_back(t + 3, server.snapshot());
        while (!down.empty() && down.front().first <= t) { client.receiveSnapshot(down.front().second); down.pop_front(); }
        if (t == 22) yAt22 = client.position().second;
        if (t == 23) yAt23 = client.position().second;
    }
    CHECK_EQ(yAt22, 500);
    CHECK_EQ(yAt23, 100);
    for (const auto& entry : up) server.receiveInput(me, entry.second);
    server.tick();
    const Snapshot s{ server.snapshot() };
    client.receiveSnapshot(s);
    CHECK_EQ(client.pendingInputs(), 0u);
    CHECK(!s.players.empty() && client.position() == std::pair{ s.players[0].x, s.players[0].y });
    CHECK(client.position() == std::pair{ 165, 100 });
}
TEST("the client clamps its own inputs") {
    GameClient client{ 1, 5, 0, 0 };
    const Input in{ client.makeInput(5, -9) };
    CHECK(in.sequence == 1 && in.moveX == 1 && in.moveY == -1);
    CHECK(client.position() == std::pair{ 5, 0 });
    CHECK_EQ(client.pendingInputs(), 1u);
}
TEST("other players from snapshots") {
    GameClient client{ 1, 5, 0, 0 };
    CHECK(!client.remotePosition(2, 10).has_value());
    client.receiveSnapshot({ 10, { { 1, 0, 0, 0 }, { 2, 100, 50, 0 } } });
    client.receiveSnapshot({ 12, { { 2, 120, 70, 0 } } });
    client.receiveSnapshot({ 11, { { 2, 999, 999, 0 } } });
    CHECK(isAt(client.remotePosition(2, 11), 110, 60));
    CHECK(isAt(client.remotePosition(2, 11.5), 115, 65));
    CHECK(isAt(client.remotePosition(2, 9), 100, 50));
    CHECK(isAt(client.remotePosition(2, 13), 120, 70));
    CHECK(!client.remotePosition(1, 10).has_value());
    CHECK(!client.remotePosition(3, 10).has_value());
    for (int t{ 13 }; t < 60; ++t) client.receiveSnapshot({ t, { { 2, t, 0, 0 } } });
    CHECK(isAt(client.remotePosition(2, 0), 28, 0));
}
TEST("lag compensation") {
    GameServer server{ 10 };
    server.addPlayer(300, 100);
    server.addPlayer(100, 500);
    for (int t{ 1 }; t <= 25; ++t) {
        server.receiveInput(2, { static_cast<std::uint32_t>(t), 1, 0 });
        server.tick();
    }
    CHECK_EQ(server.hitscan(1, 20, 0, 1, 1000, 5), 2);
    CHECK_EQ(server.hitscan(1, 25, 0, 1, 1000, 5), 0);
    CHECK_EQ(server.hitscan(1, 19.5, 0, 1, 1000, 5), 2);
    CHECK_EQ(server.hitscan(1, 19.4, 0, 1, 1000, 5), 0);
    CHECK_EQ(server.hitscan(1, 100, 0, 1, 1000, 5), 0);
    for (int t{ 26 }; t <= 60; ++t) {
        server.receiveInput(2, { static_cast<std::uint32_t>(t), 1, 0 });
        server.tick();
    }
    CHECK_EQ(server.hitscan(1, 20, 0, 1, 1000, 5), 0);
    CHECK_EQ(server.hitscan(1, 20, 1, 5, 1000, 5), 2);
    CHECK_EQ(server.hitscan(1, 60, 1, 1, 1000, 5), 2);
}
TEST("the nearest target is hit") {
    GameServer server{ 10 };
    server.addPlayer(300, 100);
    server.addPlayer(300, 500);
    server.addPlayer(300, 300);
    CHECK_EQ(server.hitscan(1, 0, 0, 1, 1000, 5), 0);
    server.tick();
    CHECK_EQ(server.hitscan(1, 1, 0, 1, 1000, 5), 3);
    CHECK_EQ(server.hitscan(1, 1, 0, -1, 1000, 5), 0);
    CHECK_EQ(server.hitscan(1, 1, 0, 1, 150, 5), 0);
    CHECK_EQ(server.hitscan(3, 1, 0, 1, 1000, 5), 2);
    CHECK_EQ(server.hitscan(9, 1, 0, 1, 1000, 5), 0);
    CHECK_EQ(server.hitscan(1, 1, 0, 0, 1000, 5), 0);
}

